```cpp
#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    std::string html;
    std::string line;
    std::istringstream iss(markdown);

    while (std::getline(iss, line)) {
        // Convert each line to HTML
        html += "<p>" + line + "</p>";
    }

    return html;
}

int main() {
    std::string markdown = "# Heading\n\nThis is a first line.\n\nThis is a second line.\n\nThis is a third line.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

